/**
 * Alerts page.
 *
 * Ordered by severity then recency, because an operator opening this view is
 * looking for the thing that needs them now. Alert text is generated by the
 * backend from its own arithmetic; this page only filters, groups, and offers
 * the resolve action.
 */

import { useCallback, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { api } from '../services/api'
import { useApi } from '../hooks/useApi'
import {
  EmptyState,
  ErrorState,
  SeverityBadge,
  Skeleton,
} from '../components/ui'
import { POLL_INTERVAL_MS } from '../utils/constants'
import {
  ALERT_TYPE_LABELS,
  formatDateTime,
  humanise,
} from '../utils/format'

const SEVERITY_RANK = { Critical: 0, Warning: 1, Info: 2 }

const FILTERS = [
  { key: 'all', label: 'All' },
  { key: 'unresolved', label: 'Open' },
  { key: 'resolved', label: 'Resolved' },
]

export function AlertsPage() {
  const [filter, setFilter] = useState('unresolved')
  const [severity, setSeverity] = useState('')
  const [type, setType] = useState('')
  const [equipmentId, setEquipmentId] = useState('')
  const [busy, setBusy] = useState(null)
  const [actionError, setActionError] = useState(null)

  const params = {
    limit: 200,
    ...(filter === 'unresolved' ? { resolved: false } : {}),
    ...(filter === 'resolved' ? { resolved: true } : {}),
    ...(severity ? { severity } : {}),
    ...(type ? { alert_type: type } : {}),
    ...(equipmentId ? { equipment_id: equipmentId } : {}),
  }

  const alerts = useApi(
    (signal) => api.alerts.list(params, { signal }),
    [filter, severity, type, equipmentId],
    { pollMs: POLL_INTERVAL_MS },
  )

  const runAction = useCallback(
    async (action, alertId) => {
      setBusy(alertId)
      setActionError(null)
      try {
        await action(alertId)
        alerts.refresh()
      } catch (error) {
        setActionError(error)
      } finally {
        setBusy(null)
      }
    },
    [alerts],
  )

  // Memoed so the grouping memos below do not rebuild on every render.
  const items = useMemo(() => alerts.data?.items ?? [], [alerts.data])

  // Group by equipment so an operator sees one machine's alerts together
  // rather than a flat chronological list split across pages.
  const groups = useMemo(() => {
    const sorted = [...items].sort((a, b) => {
      const bySeverity = (SEVERITY_RANK[a.severity] ?? 3) - (SEVERITY_RANK[b.severity] ?? 3)
      if (bySeverity !== 0) return bySeverity
      return new Date(b.timestamp) - new Date(a.timestamp)
    })

    const map = new Map()
    for (const alert of sorted) {
      if (!map.has(alert.equipment_id)) {
        map.set(alert.equipment_id, { equipment_id: alert.equipment_id, alerts: [] })
      }
      map.get(alert.equipment_id).alerts.push(alert)
    }
    return [...map.values()]
  }, [items])

  const summary = alerts.data
  const alertTypes = useMemo(
    () => [...new Set(items.map((a) => a.alert_type))].sort(),
    [items],
  )

  return (
    <div className="space-y-4">
      {alerts.error ? (
        <ErrorState error={alerts.error} onRetry={alerts.refresh} />
      ) : null}
      {actionError ? <ErrorState error={actionError} title="Action failed" /> : null}

      {/* Counts */}
      <section className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <CountCard
          label="Open"
          value={summary?.unresolved_total ?? 0}
          tone={(summary?.unresolved_total ?? 0) > 0 ? 'caution' : 'neutral'}
        />
        <CountCard
          label="Critical"
          value={summary?.counts_by_severity?.Critical ?? 0}
          tone={(summary?.counts_by_severity?.Critical ?? 0) > 0 ? 'bad' : 'neutral'}
        />
        <CountCard
          label="Warning"
          value={summary?.counts_by_severity?.Warning ?? 0}
          tone="neutral"
        />
        <CountCard label="Info" value={summary?.counts_by_severity?.Info ?? 0} tone="neutral" />
      </section>

      {/* Filters */}
      <div className="card">
        <div className="flex flex-wrap items-end gap-3 px-4 py-3">
          <div>
            <span className="label">State</span>
            <div className="flex gap-0.5 rounded border border-ink-300 bg-white p-0.5">
              {FILTERS.map((option) => (
                <button
                  key={option.key}
                  type="button"
                  onClick={() => setFilter(option.key)}
                  className={`rounded px-2.5 py-1 text-2xs font-medium transition-colors ${
                    filter === option.key
                      ? 'bg-ink-800 text-white'
                      : 'text-ink-600 hover:bg-ink-100'
                  }`}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>

          <div className="w-full sm:w-36">
            <label className="label" htmlFor="alert-severity">Severity</label>
            <select
              id="alert-severity"
              className="input"
              value={severity}
              onChange={(event) => setSeverity(event.target.value)}
            >
              <option value="">Any</option>
              <option value="Critical">Critical</option>
              <option value="Warning">Warning</option>
              <option value="Info">Info</option>
            </select>
          </div>

          <div className="w-full sm:w-48">
            <label className="label" htmlFor="alert-type">Type</label>
            <select
              id="alert-type"
              className="input"
              value={type}
              onChange={(event) => setType(event.target.value)}
            >
              <option value="">All types</option>
              {alertTypes.map((value) => (
                <option key={value} value={value}>
                  {ALERT_TYPE_LABELS[value] ?? humanise(value)}
                </option>
              ))}
            </select>
          </div>

          <div className="w-full sm:w-44">
            <label className="label" htmlFor="alert-equipment">Equipment</label>
            <input
              id="alert-equipment"
              type="search"
              className="input"
              placeholder="Equipment ID"
              value={equipmentId}
              onChange={(event) => setEquipmentId(event.target.value.toUpperCase())}
            />
          </div>

          <div className="ml-auto text-2xs text-ink-500">
            {alerts.loading ? 'Loading…' : `${items.length} shown`}
          </div>
        </div>
      </div>

      {/* Grouped list */}
      {alerts.loading && groups.length === 0 ? (
        <div className="card space-y-2 p-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} className="h-12 w-full" />
          ))}
        </div>
      ) : groups.length === 0 ? (
        <div className="card">
          <EmptyState
            title="No alerts match these filters"
            message={
              filter === 'unresolved'
                ? 'Nothing currently requires attention on this fleet.'
                : 'Try widening the state, severity, or type filter.'
            }
          />
        </div>
      ) : (
        groups.map((group) => (
          <section key={group.equipment_id} className="card">
            <div className="card-header">
              <Link
                to={`/equipment/${encodeURIComponent(group.equipment_id)}`}
                className="font-mono text-xs font-semibold text-ink-800 hover:underline"
              >
                {group.equipment_id}
              </Link>
              <span className="text-2xs text-ink-500">
                {group.alerts.length} alert{group.alerts.length === 1 ? '' : 's'}
              </span>
            </div>
            <ul className="divide-y divide-ink-100">
              {group.alerts.map((alert) => (
                <li
                  key={alert.alert_id}
                  className="flex flex-wrap items-start gap-3 px-4 py-3"
                >
                  <SeverityBadge severity={alert.severity} />

                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-ink-800">
                      {ALERT_TYPE_LABELS[alert.alert_type] ?? humanise(alert.alert_type)}
                    </p>
                    <p className="mt-0.5 text-2xs leading-relaxed text-ink-600">
                      {alert.description}
                    </p>
                    {alert.recommended_action ? (
                      <p className="mt-1 text-2xs leading-relaxed text-ink-500">
                        <span className="font-medium">Action:</span>{' '}
                        {alert.recommended_action}
                      </p>
                    ) : null}
                    <p className="mt-1 text-2xs text-ink-500">
                      {formatDateTime(alert.timestamp)}
                      {alert.observed_value ? ` · observed ${alert.observed_value}` : ''}
                      {alert.resolved_at
                        ? ` · resolved ${formatDateTime(alert.resolved_at)}`
                        : ''}
                    </p>
                  </div>

                  <div className="flex shrink-0 gap-2">
                    {!alert.acknowledged && !alert.resolved ? (
                      <button
                        type="button"
                        className="btn-ghost"
                        disabled={busy === alert.alert_id}
                        onClick={() =>
                          runAction((id) => api.alerts.acknowledge(id), alert.alert_id)
                        }
                      >
                        Acknowledge
                      </button>
                    ) : null}
                    {!alert.resolved ? (
                      <button
                        type="button"
                        className="btn-secondary"
                        disabled={busy === alert.alert_id}
                        onClick={() =>
                          runAction(
                            (id) => api.alerts.resolve(id, 'Closed from the alerts view'),
                            alert.alert_id,
                          )
                        }
                      >
                        {busy === alert.alert_id ? 'Working…' : 'Resolve'}
                      </button>
                    ) : (
                      <span className="px-2 py-1 text-2xs text-ink-500">Resolved</span>
                    )}
                  </div>
                </li>
              ))}
            </ul>
          </section>
        ))
      )}
    </div>
  )
}

function CountCard({ label, value, tone }) {
  const tones = {
    neutral: 'text-ink-900',
    caution: 'text-amber-700',
    bad: 'text-red-700',
  }
  return (
    <div className="card px-4 py-3">
      <p className="text-2xs font-semibold uppercase tracking-wider text-ink-500">{label}</p>
      <p className={`tabular mt-1 text-2xl font-semibold leading-none ${tones[tone] ?? tones.neutral}`}>
        {value}
      </p>
    </div>
  )
}
